        "SYS_bsdthread_terminate",
        "SYS_change_fdguard_np",
        "SYS_chdir",
        "SYS_chmod",
        "SYS_chmod_extended",
        "SYS_close",
        "SYS_close_nocancel",
        "SYS_connect",
        "SYS_connect_nocancel",
        "SYS_connectx",
        "SYS_csops",
        "SYS_csops_audittoken",
        "SYS_csrctl",
        "SYS_dup",
        "SYS_dup2",
        "SYS_exit",
        "SYS_faccessat",
